-- Тема 05: правки по отчёту Codex (24 исправлений в 13 вопросах), ключи не меняются.
-- Источник: scripts/questions/093_codex_topic05_fixes.js
-- Повторный запуск безопасен: вопрос и вариант ищутся по тексту, прежнее или уже новое значение допустимо,
-- иначе пакет отменяется. Ключи ответов, число и порядок вариантов не меняются.

BEGIN;
SET LOCAL standard_conforming_strings = on;
LOCK TABLE questions IN SHARE ROW EXCLUSIVE MODE;

DO $fix$
DECLARE fix record; matches integer; qid integer; k text;
BEGIN
    FOR fix IN SELECT * FROM (VALUES
        ('question', 'В каком случае транзакция будет ждать освобождения блокировки строки?', NULL, NULL, NULL, 'Транзакция выполняет обычные SELECT и UPDATE. В каком случае она будет ждать освобождения блокировки строки?'),
        ('question', 'Строка уже зафиксирована. Транзакция A изменила её командой UPDATE и ещё не завершилась. Второй сеанс работает на уровне Read Committed и обращается к этой строке. Что произойдёт?', NULL, NULL, NULL, 'Строка уже зафиксирована. Транзакция A изменила её командой UPDATE и ещё не завершилась. Второй сеанс работает на уровне Read Committed и обращается к этой строке обычным SELECT (без FOR UPDATE и FOR SHARE) или командой UPDATE. Что произойдёт?'),
        ('question', 'Снимок данных построен, когда все упомянутые транзакции уже завершились. Какие версии строки в него попадут?', NULL, NULL, NULL, 'Снимок данных построен, когда все упомянутые транзакции уже завершились. Номер в xmax оставлен удалением или изменением строки, а не её блокировкой. Какие версии строки в него попадут?'),
        ('question', 'На каком уровне определяется горизонт очистки?', NULL, NULL, NULL, 'На каком уровне определяется горизонт очистки для обычных таблиц?'),
        ('option', 'Транзакция выполняет обычные SELECT и UPDATE. В каком случае она будет ждать освобождения блокировки строки?', 'Когда пытается изменить строку, уже изменённую другой', 'При UPDATE строки, которую меняет другая транзакция', 'Когда пытается изменить строку, уже изменённую другой незафиксированной транзакцией. Изменить строку можно, когда первая транзакция завершится или откатится к более ранней точке сохранения.', 'Строку держит незавершённая транзакция. UPDATE ждёт, пока она завершится или откатится к более ранней точке сохранения.'),
        ('option', 'Строка уже зафиксирована. Транзакция A изменила её командой UPDATE и ещё не завершилась. Второй сеанс работает на уровне Read Committed и обращается к этой строке обычным SELECT (без FOR UPDATE и FOR SHARE) или командой UPDATE. Что произойдёт?', 'Обычный SELECT будет ждать завершения транзакции A', 'SELECT будет ждать, пока транзакция A не завершится', 'Многоверсионность позволяет читать без ожидания. Ждать может SELECT с блокирующим предложением, например FOR UPDATE или FOR SHARE, если запрошенная блокировка конфликтует с блокировкой A.', 'Многоверсионность позволяет читать без ожидания. Ждать мог бы SELECT FOR UPDATE или FOR SHARE, но в условии обычное чтение.'),
        ('option', 'Строка уже зафиксирована. Транзакция A изменила её командой UPDATE и ещё не завершилась. Второй сеанс работает на уровне Read Committed и обращается к этой строке обычным SELECT (без FOR UPDATE и FOR SHARE) или командой UPDATE. Что произойдёт?', 'UPDATE этой же строки будет ждать завершения транзакции A', 'UPDATE этой строки будет ждать блокировку, занятую A', 'Две записи в одну строку конфликтуют: вторая ждёт блокировку строки.', 'Две записи в одну строку конфликтуют: вторая ждёт, пока A завершится или откатится к точке сохранения, поставленной до UPDATE.'),
        ('option', 'Транзакция на уровне Repeatable Read уже час строит отчёт по таблице t1 и не завершается. Таблица t2 в той же базе всё это время активно обновляется. Что сможет сделать очистка с t2?', 'Не сможет убрать версии t2, ставшие неактуальными', 'Не уберёт версии t2, устаревшие с начала отчёта', 'Очистка не уберёт версии строк t2, ставшие неактуальными после создания снимка долгой транзакции: горизонт очистки один на базу, и его держит этот снимок, хотя транзакция не обращается к t2.', 'Версии t2, устаревшие после создания снимка долгой транзакции, очистка не уберёт: горизонт очистки один на базу, и его держит этот снимок, хотя транзакция не обращается к t2. Более старые мёртвые версии убрать можно.'),
        ('option', 'Транзакция A на уровне Read Committed прочитала строку. Транзакция B изменила эту строку командой UPDATE и ещё не зафиксировала изменения. A снова выполняет SELECT xmin, xmax, * FROM t. Что она увидит?', 'Старую версию строки, в xmax уже номер транзакции B', 'Старую версию, в xmax уже номер транзакции B', NULL, NULL),
        ('option', 'Транзакция A изменила строку и ещё не завершилась. Транзакция B выполняет UPDATE той же строки и ждёт. Затем A фиксирует изменения. Что верно?', 'B изменит старую версию строки, и изменения A пропадут', 'На Serializable UPDATE в B продолжится после проверки WHERE', 'Это было бы потерянное обновление, PostgreSQL его не допускает.', 'На Serializable будет то же, что на Repeatable Read: UPDATE получит ошибку сериализации.'),
        ('option', 'Транзакция A прочитала таблицу и ещё не завершилась. Что произойдёт, если во втором сеансе выполнить DROP TABLE для этой таблицы?', 'DROP TABLE будет ждать завершения транзакции A', 'DROP TABLE будет ждать освобождения блокировки', NULL, NULL),
        ('option', 'Транзакция A прочитала таблицу и ещё не завершилась. Что произойдёт, если во втором сеансе выполнить DROP TABLE для этой таблицы?', 'Таблица удалится сразу', 'Таблица удалится сразу, не дожидаясь транзакции A', 'Блокировка уровня таблицы этого не позволит.', 'Блокировка ACCESS SHARE, которую держит A, этого не позволит.'),
        ('option', 'На каком уровне определяется горизонт очистки для обычных таблиц?', 'Отдельно для каждой базы данных кластера', 'Отдельно для каждой базы данных', NULL, NULL),
        ('option', 'Когда строится снимок данных на уровне Repeatable Read?', 'При первом операторе с данными, не при BEGIN', 'При первом операторе после BEGIN', 'Снимок строится первым оператором, которому нужны данные (BEGIN его не создаёт), и действует до конца транзакции.', 'Снимок строится при первом операторе транзакции, не считая BEGIN и других команд управления транзакцией, и действует до её конца.'),
        ('option', 'Что верно для уровня изоляции Read Committed?', 'Два одинаковых запроса могут вернуть разные данные', 'Повтор запроса в транзакции может дать другие данные', NULL, NULL),
        ('option', 'Чем опасна долгая транзакция?', 'Сбрасывает накопительную статистику сервера', 'Сбрасывает накопительную статистику всего сервера', NULL, NULL),
        ('option', 'Чем опасна долгая транзакция?', 'Может удерживать горизонт очистки и раздувать таблицы', 'Может держать горизонт очистки, раздувая таблицы', NULL, NULL),
        ('option', 'Почему откат транзакции в PostgreSQL выполняется быстро, без отмены каждого изменения?', 'Версии не нужно возвращать: статус прерванной в clog', 'Откат меняет статус транзакции, сохраняя версии строк', NULL, NULL),
        ('option', 'Что должно уметь приложение, работающее на уровне изоляции Serializable?', 'Выполнять каждую команду в отдельной транзакции', 'Повторять упавшую команду, продолжая транзакцию', 'Смысл уровня как раз в изоляции многооператорных транзакций.', 'После ошибки сериализации транзакция прервана, продолжить её нельзя: повторяют всю транзакцию с начала.'),
        ('option', 'Что должно уметь приложение, работающее на уровне изоляции Serializable?', 'Явно блокировать все строки, которые она читает', 'Явно блокировать все строки, которые транзакция читает', NULL, NULL),
        ('option', 'Что должно уметь приложение, работающее на уровне изоляции Serializable?', 'Повторять транзакции, прерванные ошибкой сериализации', 'Повторять всю транзакцию после ошибки сериализации', NULL, NULL),
        ('explanation', 'Снимок данных построен, когда все упомянутые транзакции уже завершились. Номер в xmax оставлен удалением или изменением строки, а не её блокировкой. Какие версии строки в него попадут?', NULL, NULL, 'Статус транзакций из xmin и xmax берётся из clog. При откате версии строк остаются в странице, их пропускают правила видимости, а позже убирает очистка.', 'Статус транзакций из xmin и xmax берётся из clog. Версии, созданные отменённой транзакцией, остаются в странице: их пропускают правила видимости, а позже убирает очистка. Если отменено удаление, прежняя версия остаётся видимой.'),
        ('explanation', 'Транзакция A на уровне Read Committed прочитала строку. Транзакция B изменила эту строку командой UPDATE и ещё не зафиксировала изменения. A снова выполняет SELECT xmin, xmax, * FROM t. Что она увидит?', NULL, NULL, 'Ненулевой xmax означает, что какая-то транзакция удалила или заменила эту версию. Видна ли версия, зависит от того, зафиксирована ли эта транзакция и попала ли в снимок. По служебным полям видно, что версия ещё видна, хотя уже не актуальна. Когда B зафиксирует изменения, следующий запрос A на Read Committed увидит новую версию.', 'UPDATE транзакции B сразу записал её номер в xmax старой версии. Видна ли версия, зависит от того, зафиксирована ли эта транзакция и попала ли в снимок. По служебным полям видно, что версия ещё видна, хотя уже не актуальна. Когда B зафиксирует изменения, следующий запрос A на Read Committed увидит новую версию.'),
        ('explanation', 'Транзакция A прочитала таблицу и ещё не завершилась. Что произойдёт, если во втором сеансе выполнить DROP TABLE для этой таблицы?', NULL, NULL, 'Чтение таблицы удерживает блокировку ACCESS SHARE до конца транзакции. DROP TABLE требует несовместимую с ней блокировку ACCESS EXCLUSIVE и поэтому ждёт.', 'Чтение таблицы берёт блокировку ACCESS SHARE и держит её до конца транзакции или до отката к более ранней точке сохранения. DROP TABLE требует несовместимую с ней блокировку ACCESS EXCLUSIVE и поэтому ждёт.')
    ) AS fixes(kind, question_text, opt_text, new_opt_text, old_text, new_text)
    LOOP
        -- Сначала ровно один вопрос по тексту (прежнему или новому), дальше всё только по его id.
        SELECT count(*), min(id) INTO matches, qid FROM questions
        WHERE question_text IN (fix.question_text, CASE WHEN fix.kind = 'question' THEN fix.new_text ELSE fix.question_text END);
        IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вопрос для исправления'; END IF;
        IF fix.kind = 'question' THEN
            UPDATE questions SET question_text = fix.new_text WHERE id = qid;
        ELSIF fix.kind = 'explanation' THEN
            PERFORM 1 FROM questions WHERE id = qid AND explanation IN (fix.old_text, fix.new_text);
            IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение вопроса'; END IF;
            UPDATE questions SET explanation = fix.new_text WHERE id = qid;
        ELSE
            SELECT count(*), min(o.key) INTO matches, k
            FROM questions q, jsonb_each_text(q.options) o
            WHERE q.id = qid AND o.value IN (fix.opt_text, coalesce(fix.new_opt_text, fix.opt_text));
            IF matches <> 1 THEN RAISE EXCEPTION 'Не найден единственный вариант ответа для исправления'; END IF;
            IF fix.new_text IS NOT NULL THEN
                PERFORM 1 FROM questions WHERE id = qid AND option_notes ->> k IN (fix.old_text, fix.new_text);
                IF NOT FOUND THEN RAISE EXCEPTION 'Неожиданное пояснение варианта'; END IF;
                UPDATE questions SET option_notes = jsonb_set(option_notes, ARRAY[k], to_jsonb(fix.new_text)) WHERE id = qid;
            END IF;
            IF fix.new_opt_text IS NOT NULL THEN
                UPDATE questions SET options = jsonb_set(options, ARRAY[k], to_jsonb(fix.new_opt_text)) WHERE id = qid;
            END IF;
        END IF;
    END LOOP;
END
$fix$;

COMMIT;
